def poly2(x,v,deg):
    cols=[]
    for i in range(deg+1):
        for j in range(deg+1-i):
            cols.append(x**i*v**j)
    return cols
for deg in [3,4,5,6]:
    best=None
    for w in np.linspace(0.30,0.33,121):
        A=np.column_stack(poly2(x,v,deg)+[np.cos(w*t),np.sin(w*t)])
        c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
        r=np.var(dv_dt-A@c)/np.var(dv_dt)
        if best is None or r<best[0]: best=(r,w)
    print(deg,best)

